"""SYNTHETIC test case for calibration (AN_v1).

*** Everything in this module is SYNTHETIC: forcing, 'true' parameters and observations are
*** generated by a seeded random number generator.  They are NOT field data and say nothing
*** about any real site.  They exist only to test that DREAM and PEST++ can recover known
*** parameters and to compare their uncertainty estimates.

Treatment train (units in series):
  1. woodchip denitrifying bioreactor : 4 tanks in series, Michaelis-Menten NO3-N removal,
                                        Arrhenius temperature dependence
  2. eggshell P-sorption reactor      : 3 tanks in series, kinetic Langmuir sorption with
                                        finite capacity that depletes
High-flow bypass above the design flow in both units.
Observations: flow-weighted concentration of NO3-N and PO4-P at the train outlet (after the
bypass junction), every 3rd day, with heteroscedastic Gaussian noise.
"""
import numpy as np
from .model_AN_v1 import Unit, Forcing, simulate_train, train_balance

# ---- calibrated parameters: name, true value, lower, upper, transform ---------------------------
PARAMS = [  # name,        true,   lo,     hi,    log10?
    ("vmax_N",   7.0,    0.5,    40.0,  True),    # g N / m3 pore water / d at 20 degC
    ("K_N",      3.0,    0.1,    30.0,  True),    # g N / m3
    ("theta_N",  1.08,   1.00,   1.25,  False),   # Arrhenius
    ("k_ads",    0.006,  1e-4,   0.05,  True),    # m3 / g / d
    ("q_max",    0.9,    0.05,   6.0,   True),    # g P / kg eggshell
]
NAMES = [p[0] for p in PARAMS]
TRUE = np.array([p[1] for p in PARAMS])
LO = np.array([p[2] for p in PARAMS])
HI = np.array([p[3] for p in PARAMS])
LOG = np.array([p[4] for p in PARAMS])

# fixed (known) design / system properties of the synthetic site
WOOD = dict(name="woodchip", n_cells=4, volume=30.0, q_design=50.0, scheme="upwind",
            n_kinetics="mm", cN0=9.0, cP0=0.5)
EGG = dict(name="eggshell", n_cells=3, volume=1.5, q_design=50.0, scheme="upwind",
           p_kinetics="langmuir", rho_bulk_over_theta=1100.0 / 0.45, k_des=0.001, theta_p=1.0,
           cN0=9.0, cP0=0.5)

NOISE_N = (0.15, 0.05)       # sigma = a + b * y_true   (g/m3)
NOISE_P = (0.01, 0.05)


def to_internal(x):        # physical -> sampling space (log10 for positive-scale parameters)
    x = np.asarray(x, float)
    return np.where(LOG, np.log10(x), x)


def to_physical(z):
    z = np.asarray(z, float)
    return np.where(LOG, 10.0 ** z, z)


Z_LO, Z_HI, Z_TRUE = to_internal(LO), to_internal(HI), to_internal(TRUE)


def make_forcing(seed=2026, days=365) -> Forcing:
    """Synthetic daily forcing for one year with storms that exceed the design flow."""
    rng = np.random.default_rng(seed)
    d = np.arange(days)
    season = np.sin(2 * np.pi * (d - 100) / 365)
    Q = 18.0 * (1 + 0.5 * np.exp(-((d - 105) / 30.0) ** 2)) * rng.lognormal(0, 0.25, days)
    for _ in range(14):                               # storm events
        s = rng.integers(0, days - 3); dur = rng.integers(1, 4)
        Q[s:s + dur] += rng.uniform(40, 110)
    T = np.clip(10.5 + 10.5 * season + rng.normal(0, 1.2, days), 0.5, None)
    cinN = np.clip(9.0 + 3.0 * np.cos(2 * np.pi * (d - 60) / 365) + rng.normal(0, 1.0, days), 2, None)
    cinP = np.clip(0.55 + 0.25 * np.tanh((Q - 30) / 30) + rng.normal(0, 0.08, days), 0.08, None)
    return Forcing(Q, T, cinN, cinP, dt=1.0, start="2025-01-01")


def build_train(x):
    """x: physical parameter vector in PARAMS order -> list of Units."""
    vmax, KN, thN, kads, qmax = [float(v) for v in x]
    wood = Unit(vmax_n=vmax, K_n=KN, theta_n=thN, **WOOD)
    egg = Unit(k_ads=kads, q_max=qmax, **EGG)
    return [wood, egg]


def run_model(x, forcing: Forcing, tol=1e-6, nsub=None):
    """Run the train.  Returns dict with outlet series, per-unit and train balances, kg retained/yr."""
    rs = simulate_train(build_train(x), forcing, nsub=nsub, tol=tol)
    tb = train_balance(rs, tol)
    return dict(cN=rs[-1].cout_N, cP=rs[-1].cout_P, kgN=rs[0].balance()["kgN_retained_per_yr"],
                kgP=rs[1].balance()["kgP_retained_per_yr"], results=rs, train_balance=tb)


OBS_DAYS = np.arange(2, 365, 3)


def make_observations(forcing: Forcing, seed=7):
    """Synthetic observations from the TRUE parameters + heteroscedastic noise."""
    out = run_model(TRUE, forcing)
    rng = np.random.default_rng(seed)
    yN, yP = out["cN"][OBS_DAYS], out["cP"][OBS_DAYS]
    sN = NOISE_N[0] + NOISE_N[1] * yN
    sP = NOISE_P[0] + NOISE_P[1] * yP
    oN = yN + rng.normal(0, sN); oP = yP + rng.normal(0, sP)
    return dict(days=OBS_DAYS, obsN=np.clip(oN, 0.0, None), obsP=np.clip(oP, 0.0, None),
                trueN=yN, trueP=yP, true_kgN=out["kgN"], true_kgP=out["kgP"])


def obs_sigma(obs):
    """Error model (known for the synthetic case): sigma_i = a + b * observed value (the usual
    way weights are assigned in PEST).  The same sigmas are used by DREAM (fixed-sigma run)."""
    return (NOISE_N[0] + NOISE_N[1] * obs["obsN"], NOISE_P[0] + NOISE_P[1] * obs["obsP"])
